data.query:
query GetLoadDetails($where: LoadWhereInput) {
  load(where: $where) {
    edges {
      node {
        id
        number
        sealNumber
        scheduledDepartAt
        scac {
          code
          carrier
        }
        shipments {
          edges {
            node {
              id
              bolNumber
              trackingNumber
              proNumber
              businessPartnerAddress {
                businessPartner {
                  code
                  name
                }
                address {
                  lines
                  city
                  state
                  country
                  postalCode
                }
              }
              shipmentLines {
                edges {
                  node {
                    quantity {
                      value
                      unitId
                    }
                    inventories {
                      edges {
                        node {
                          id
                          handlingUnitId
                          quantity {
                            value
                            unitId
                            unit {
                              id
                              name
                            }
                          }
                          lot {
                            number
                          }
                          product {
                            code
                            name
                            description
                            weight {value unitId}
                            length {value unitId}
                            width {value unitId}
                            height {value unitId}
                          }
                          inventoryPickSteps {
                            edges {
                              node {
                                pickStep {
                                  orderLineRelease {
                                    orderLine {
                                      orderId
                                    }
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
        orders {
          edges {
            node {
              id
              number
              specialInstructions
              orderLines {
                total
                edges {
                  node {
                    unitPrice
                    product {
                      code
                      name
                      description
                    }
                    orderLineReleases {
                      edges {
                        node {
                          quantity {
                            value
                            unitId
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
        handlingUnits {
          total
          edges {
            node {
              id
              barcode
              volume {
                value
                unitId
              }
              weight {
                value
                unitId
              }
              handlingUnitType {
                id
                name
              }
            }
          }
        }
      }
    }
  }
}

